/* eslint-disable no-useless-escape */
export const glslMonacoLanguage = {
  configuration: {
    wordPattern: /(-?\d*\.\d\w*)|([^`~!#$%^&*()\-=+[{\]}\\|;:'",.<>/?\s]+)/g,
    comments: {
      lineComment: "//",
      blockComment: ["/*", "*/"],
    },
    brackets: [
      ["{", "}"],
      ["[", "]"],
      ["(", ")"],
    ],
    autoClosingPairs: [
      { open: "[", close: "]" },
      { open: "{", close: "}" },
      { open: "(", close: ")" },
      { open: "'", close: "'", notIn: ["string", "comment"] },
      { open: '"', close: '"', notIn: ["string"] },
    ],
  },

  tokenProvider: {
    defaultToken: "invalid",
    tokenPostfix: ".glsl",
    typeKeywords: [
      "bool", "bvec2", "bvec3", "bvec4", "float", "int", "ivec2", "ivec3", "ivec4", 
      "mat2", "mat2x2", "mat2x3", "mat2x4", "mat3", "mat3x2", "mat3x3", "mat3x4", "mat4", "mat4x2", "mat4x3", "mat4x4",
      "uint", "uvec2", "uvec3", "uvec4", "vec2", "vec3", "vec4", "void",
    ],
    keywords: [
      "attribute", "break", "case", "centroid", "const", "continue", "default",
      "discard", "do", "else", "false", "flat", "for", "highp", "if", "in", "inout",
      "invariant", "isampler2D", "isampler2DArray", "isampler3D", "isamplerCube",
      "layout", "lowp", "mediump", "out", "precision", "return", "sampler2D", "sampler2DArray",
      "sampler2DArrayShadow", "sampler2DShadow", "sampler3D", "samplerCube", "samplerCubeShadow",
      "smooth", "struct", "switch", "true", "uniform", "usampler2D", "usampler2DArray", "usampler3D",
      "usamplerCube", "varying", "while",
    ],
    functions: [
      "radians", "degrees", "sin", "cos", "tan", "asin", "acos", "atan",
      "sinh", "cosh", "tanh", "asinh", "acosh", "atanh", "pow", "exp", "log", "exp2", "log2",
      "sqrt", "inversesqrt", "abs", "sign", "floor", "trunc", "round", "roundEven", "ceil", "fract",
      "mod", "modf", "min", "max", "clamp", "mix", "step", "smoothstep", "isnan", "isinf", "floatBitsToInt",
      "floatBitsToUint", "intBitsToFloat", "uintBitsToFloat", "packSnorm2x16", "unpackSnorm2x16",
      "packUnorm2x16", "unpackUnorm2x16", "packHalf2x16", "unpackHalf2x16", "length", "distance",
      "dot", "cross", "normalize", "faceforward", "reflect", "refract", "matrixCompMult",
      "outerProduct", "transpose", "determinant", "inverse", "lessThan", "lessThanEqual", "greaterThan",
      "greaterThanEqual", "equal", "notEqual", "any", "all", "not", "textureSize", "texture",
      "texture2D", "textureCube", "texture2DProj", "texture2DLodEXT", "texture2DProjLodEXT", "textureCubeLodEXT",
      "texture2DGradEXT", "texture2DProjGradEXT", "textureCubeGradEXT", "textureProj", "textureLod",
      "textureOffset", "texelFetch", "texelFetchOffset", "textureProjOffset", "textureLodOffset", "textureProjLod",
      "textureProjLodOffset", "textureGrad", "textureGradOffset", "textureProjGrad", "textureProjGradOffset",
      "dFdx", "dFdy", "fwidth",
    ],
    operators: [
      "++", "--", "+", "-", "~", "!", "*", "/", "%", "<<", ">>",
      "<", ">", "<=", ">=", "==", "!=", "&", "^", "|", "&&", "^^", "||",
      "?", ":", "=", "+=", "-=", "*=", "/=", "%=", "<<=", ">>=", "&=", "^=", "|=", ",",
    ],
    brackets: [
      { token: "delimiter.curly", open: "{", close: "}" },
      { token: "delimiter.parenthesis", open: "(", close: ")" },
      { token: "delimiter.square", open: "[", close: "]" },
      // { token: "delimiter.angle", open: "<", close: ">" },
    ],
    symbols: /[=><!~?:&|+\-*\/\^%]+/,
    digits: /\d+/,
    hexdigits: /[[0-9a-fA-F]+(_+[0-9a-fA-F]+)*/,
    unsignedSuffix: /[uU]?/,
    floatsuffix: /[fF]?/,
    func: /[a-zA-Z_0-9]+/,

    tokenizer: {
      root: [
        [/[{}]/, 'delimiter.bracket'],
        { include: 'common' }
      ],
      common: [
        [
          /#(version|define|undef|ifdef|ifndef|else|elsif|endif)/,
          'keyword.directive',
        ],
        // identifiers and keywords
        [/[a-z_$][\w$]*/, {
          cases: {
            '@typeKeywords': 'keyword',
            '@keywords': 'keyword',
            '@functions': 'key',
            '@default': 'identifier'
          }
        }],
        // Show capital letters in distinct style
        [/[A-Z][\w\$]*/, 'type.identifier'],
        { include: '@whitespace' },

        [/[()\[\]]/, '@brackets'],

        [/@symbols/, {
          cases: {
            '@operators': 'delimiter',
            '@default': ''
          }
        }],

        // numbers
        [/(@digits)[eE]([\-+]?(@digits))?/, 'number.float'],
        [/(@digits)?\.(@digits)([eE][\-+]?(@digits))?/, 'number.float'],
        [/(@digits)?\.(([eE][\-+]?)?(@digits))?/, 'number.float'],
        [/0[xX](@hexdigits)/, 'number.hex'],
        [/(@digits)/, 'number.hex'],

        // delimiter: after number because of .\d floats
        [/[;,.]/, 'delimiter'],
      ],
      whitespace: [
        [/[ \t\r\n]+/, ''],
        [/\/\*\*(?!\/)/, 'comment.doc', '@jsdoc'],
        [/\/\*/, 'comment', '@comment'],
        [/\/\/.*$/, 'comment'],
      ],

      comment: [
        [/[^\/*]+/, 'comment'],
        [/\*\//, 'comment', '@pop'],
        [/[\/*]/, 'comment']
      ],

      jsdoc: [
        [/[^\/*]+/, 'comment.doc'],
        [/\*\//, 'comment.doc', '@pop'],
        [/[\/*]/, 'comment.doc']
      ],

    },
  },
};

